sparql:
PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX sphn-individual: <https://biomedit.ch/rdf/sphn-schema/sphn/individual#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?event a sphn:AdverseEvent ;
           sphn:hasConsequences sphn-individual:LifeThreatening .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?death a sphn:Death ;
           sphn:hasConditionCode ?code .
    ?code a snomed:724490006 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
