PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT (COUNT(DISTINCT ?administration) AS ?administrations)
WHERE {
  GRAPH ?g {
    ?administration a sphn:DrugAdministrationEvent ;
                    sphn:hasReasonToStopCode ?code .
    ?code a snomed:182844005 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX ucum: <https://biomedit.ch/rdf/sphn-resource/ucum/>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?pressure a sphn:BloodPressure ;
              sphn:hasMeanPressure ?quantity .
    ?quantity sphn:hasValue ?value ;
              sphn:hasUnit/sphn:hasCode ?unit_code .
    ?unit_code a ucum:mmsblHgsbr .
  }
  FILTER (?value < 65)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX ucum: <https://biomedit.ch/rdf/sphn-resource/ucum/>

SELECT (COUNT(DISTINCT ?pressure) AS ?readings)
WHERE {
  GRAPH ?g {
    ?pressure a sphn:BloodPressure ;
              sphn:hasDiastolicPressure ?quantity .
    ?quantity sphn:hasValue ?value ;
              sphn:hasUnit/sphn:hasCode ?unit_code .
    ?unit_code a ucum:mmsblHgsbr .
  }
  FILTER (?value < 60)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
