PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX ucum: <https://biomedit.ch/rdf/sphn-resource/ucum/>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?exposure a sphn:TobaccoExposure ;
              sphn:hasDuration ?quantity .
    ?quantity sphn:hasValue ?value ;
              sphn:hasUnit/sphn:hasCode ?unit_code .
    ?unit_code a ucum:a .
  }
  FILTER (?value > 40)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX ucum: <https://biomedit.ch/rdf/sphn-resource/ucum/>

SELECT (MAX(?value) AS ?highest_cardiac_index_L_per_min_per_m2)
WHERE {
  GRAPH ?g {
    ?index a sphn:CardiacIndex ;
           sphn:hasQuantity ?quantity .
    ?quantity sphn:hasValue ?value ;
              sphn:hasUnit/sphn:hasCode ?unit_code .
    ?unit_code a ucum:Lperminperm2 .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX ucum: <https://biomedit.ch/rdf/sphn-resource/ucum/>

SELECT (MAX(?value) AS ?largest_body_surface_area_m2)
WHERE {
  GRAPH ?g {
    ?area a sphn:BodySurfaceArea ;
          sphn:hasQuantity ?quantity .
    ?quantity sphn:hasValue ?value ;
              sphn:hasUnit/sphn:hasCode ?unit_code .
    ?unit_code a ucum:m2 .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX ucum: <https://biomedit.ch/rdf/sphn-resource/ucum/>

SELECT (MIN(?value) AS ?lowest_systolic_mmHg)
WHERE {
  GRAPH ?g {
    ?pressure a sphn:BloodPressure ;
              sphn:hasSystolicPressure ?quantity .
    ?quantity sphn:hasValue ?value ;
              sphn:hasUnit/sphn:hasCode ?unit_code .
    ?unit_code a ucum:mmsblHgsbr .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX ucum: <https://biomedit.ch/rdf/sphn-resource/ucum/>

SELECT (AVG(?value) AS ?average_saturation_percent)
WHERE {
  GRAPH ?g {
    ?saturation a sphn:OxygenSaturation ;
                sphn:hasQuantity ?quantity .
    ?quantity sphn:hasValue ?value ;
              sphn:hasUnit/sphn:hasCode ?unit_code .
    ?unit_code a ucum:percent .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX ucum: <https://biomedit.ch/rdf/sphn-resource/ucum/>

SELECT (MAX(?value) AS ?highest_dose_Gy)
WHERE {
  GRAPH ?g {
    ?radiotherapy a sphn:RadiotherapyProcedure ;
                  sphn:hasRadiationQuantity ?quantity .
    ?quantity sphn:hasValue ?value ;
              sphn:hasUnit/sphn:hasCode ?unit_code .
    ?unit_code a ucum:Gy .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?support a sphn:OrganSupport .
  }
  FILTER EXISTS {
    GRAPH ?g { ?directive a sphn:ResuscitationDirective . }
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?transplant a sphn:TransplantPresence .
  }
  FILTER NOT EXISTS {
    GRAPH ?g { ?event a sphn:AdverseEvent . }
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?nursing a sphn:NursingDiagnosis .
  }
  FILTER NOT EXISTS {
    GRAPH ?g { ?billed a sphn:BilledDiagnosis . }
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?prescription a sphn:DrugPrescription .
  }
  FILTER NOT EXISTS {
    GRAPH ?g { ?administration a sphn:DrugAdministrationEvent . }
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?outcome (COUNT(DISTINCT ?event) AS ?events)
WHERE {
  GRAPH ?g {
    ?event a sphn:AdverseEvent ;
           sphn:hasOutcome ?outcome .
  }
}
GROUP BY ?outcome
ORDER BY DESC(?events)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?allergen (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?allergy a sphn:Allergy ;
             sphn:hasAllergen ?substance .
    ?substance sphn:hasCode ?code .
    ?code a ?allergen .
  }
  FILTER (STRSTARTS(STR(?allergen), "http://snomed.info/id/"))
}
GROUP BY ?allergen
ORDER BY DESC(?patients)
LIMIT 5

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?care_type (COUNT(DISTINCT ?case) AS ?cases)
WHERE {
  GRAPH ?g {
    ?case a sphn:AdministrativeCase ;
          sphn:hasCareHandling ?handling .
    ?handling sphn:hasTypeCode ?code .
    ?code a ?care_type .
  }
  FILTER (STRSTARTS(STR(?care_type), "http://snomed.info/id/"))
}
GROUP BY ?care_type
ORDER BY DESC(?cases)
